        /// <summary>
        /// 容器中按钮通用触发事件
        /// </summary>
        /// <param name="ButtonName">按钮名</param>
        public void ButtonClick(string ButtonName)
        {
		    //to do..
			//扫描批号和不良代码
			if (ButtonName=="MyButton")
			{
				string returnMessage="";
				int aa=DataMethod(ref returnMessage );
				//辅料条码扫描异常
				if (aa==-1)
				{
				        Scripter.SetParameterValue("AccessoryBarcodeScan",null);          
						Scripter.SetControlFocus("AccessoryBarcodeScan");
						Scripter.SetParameterValue("ScanResult","NGFace.png"); 
						Scripter.SetControlStyle("ScanResult","[Visible|1]");
				        Scripter.SetParameterValue("WarnImage","left.png");
				        MessageBox.Show(returnMessage,Scripter.PlugInCommand);
				
				
				}
				//员工号扫描异常
				if (aa==-2)
				{
				
				        Scripter.SetParameterValue("ScanOperator",null); 
						Scripter.SetControlFocus("ScanOperator");
	                 	Scripter.SetParameterValue("ScanResult","NGFace.png"); 
						Scripter.SetControlStyle("ScanResult","[Visible|1]");
				        Scripter.SetParameterValue("WarnImage","left.png");
				        MessageBox.Show(returnMessage,Scripter.PlugInCommand);
				
				}
				//扫描辅料条码
				if (aa==0)
				{
					 TAccessoryBarcodeScan =Scripter.GetParameterValue("AccessoryBarcodeScan");
				     num=num+1;
		            //判断重复
	                if (!lst.Contains( TAccessoryBarcodeScan))
					{

	                    lst.Add(TAccessoryBarcodeScan);					
				
					    //创建数据行
						DataRow dr = table.NewRow();
			
						dr["序号"]= string.Format("{0:0000}",num);
						dr["辅料条码"]=Scripter.GetParameterValue("AccessoryBarcodeScan");
						dr["工号"]=Scripter.GetParameterValue("ScanOperator");
						dr["领用时间"]=DateTime.Now.ToString("yyyy年MM月dd日HH时mm分ss秒");
				        table.Rows.Add(dr);
						DataView dv = table.DefaultView; 

						dv.Sort = "序号 DESC";  //排序 

						DataTable table1 = dv.ToTable();
						
						DataSet xmldsGrid=new DataSet();
						System.Data.DataTable dtGrid=new System.Data.DataTable();
						
						dtGrid=table1.Copy();
						xmldsGrid.Tables.Add(dtGrid);
				        //显示
						Scripter.SetParameterDataSet("LotInfo",xmldsGrid); 
						for (int i=0;i<grid.DisplayLayout.Bands[0].ColumnFilters.Count;i++)
						{
							if(Convert.ToString(grid.DisplayLayout.Bands[0].Columns[i].Header.Caption)=="辅料条码")
							{
								grid.DisplayLayout.Bands[0].Columns[i].Width=200;
							}
							if(Convert.ToString(grid.DisplayLayout.Bands[0].Columns[i].Header.Caption)=="工号")
							{
								grid.DisplayLayout.Bands[0].Columns[i].Width=80;
							}
							if(Convert.ToString(grid.DisplayLayout.Bands[0].Columns[i].Header.Caption)=="出库时间")
							{
								grid.DisplayLayout.Bands[0].Columns[i].Width=100;
							}
						}
					   //
						Scripter.SetParameterValue("AccessoryBarcodeScan",null); 
						Scripter.SetControlFocus("AccessoryBarcodeScan");
						Scripter.SetParameterValue("ScanResult","OKFace.png"); 
						Scripter.SetControlStyle("ScanResult","[Visible|1]");
				        Scripter.SetParameterValue("WarnImage","right.png");
						Scripter.ShowMessage(returnMessage,false);
						
	                }
	                else 
					{ 
					    Scripter.SetParameterValue("AccessoryBarcodeScan",null); 
						Scripter.SetControlFocus("AccessoryBarcodeScan");
						Scripter.SetParameterValue("ScanResult","NGFace.png"); 
						Scripter.SetControlStyle("ScanResult","[Visible|1]");
				        Scripter.SetParameterValue("WarnImage","left.png");
	                    MessageBox.Show("扫描重复： "+Scripter.GetParameterValue("AccessoryBarcodeScan"),Scripter.PlugInCommand);
	 
	                }
				
				
				}
			
			   
			}
			

			
        }

