		/// 数据处理
		/// </summary>
		public int DataMethod( ref string returnMessage)
        {		
		    int result=-1;
			string AccessoryBarcodeScan=Scripter.GetParameterValue("AccessoryBarcodeScan");
		    string WorkcenterName=Scripter.GetParameterValue("WorkcenterName");
			string ScanOperator=Scripter.GetParameterValue("ScanOperator");
			string OrBitUserId=Scripter.OrBitUserId;
			string PlugInCommand=Scripter.PlugInCommand;
			string ResourceId=Scripter.ResourceId;
			try
			{
				string str=@"DECLARE @return_value int,
									@I_ReturnMessage nvarchar(max)

						EXEC @return_value = [dbo].[Txn_AccessoryStirDoMethod]
							@I_ReturnMessage =@I_ReturnMessage OUTPUT,
							@I_OrBitUserId = N'"+OrBitUserId+@"',  
							@I_PlugInCommand = N'"+PlugInCommand+@"',  
							@I_ResourceId = N'"+ResourceId+@"',
							@AccessoryBarcodeScan = N'"+AccessoryBarcodeScan+@"',
							@WorkcenterName = N'"+WorkcenterName+@"',
							@ScanOperator = N'"+ScanOperator+@"'
                     SELECT   @return_value as N'return_value',
                             @I_ReturnMessage as N'I_ReturnMessage'";				

				//执行 SQL 语句
		        DataSet ds=Scripter.GetSqlDataSet(str);
				
				returnMessage=Convert.ToString(ds.Tables[0].Rows[0]["I_ReturnMessage"]);
				
				result=int.Parse(Convert.ToString(ds.Tables[0].Rows[0]["return_value"]));
			
	
			}
			catch(Exception ex)
			{
				returnMessage=ex.Message;			
			}
			
			return result ;
			
		}
	

